steps.script:
# A LIGHT terrain area round the Flash Gitz, 1" past every base: every model
# within it (13.09: within = any part of the base), so they are Hidden.
var fg = GameState.state["units"]["U_FLASH_GITZ_A"]
fg["flags"] = {}
var lo = Vector2(INF, INF)
var hi = Vector2(-INF, -INF)
for m in fg["models"]:
	if not m.get("alive", true) or m.get("position") == null:
		continue
	var p = Vector2(float(m.position.x), float(m.position.y))
	lo = Vector2(min(lo.x, p.x), min(lo.y, p.y))
	hi = Vector2(max(hi.x, p.x), max(hi.y, p.y))
var pad = 60.0
var poly = PackedVector2Array([Vector2(lo.x - pad, lo.y - pad), Vector2(hi.x + pad, lo.y - pad), Vector2(hi.x + pad, hi.y + pad), Vector2(lo.x - pad, hi.y + pad)])
var area = {"id": "fg_light_area", "piece_class": "area", "type": "woods", "category": "light", "height_category": "low", "polygon": poly, "can_move_through": {"INFANTRY": true, "VEHICLE": true, "MONSTER": true}}
TerrainManager.terrain_features.append(area)
GameState.state["board"]["terrain_features"] = TerrainManager.terrain_features.duplicate(true)
RulesEngine.clear_los_memo()
var n = 0
var t = 0
for m in fg["models"]:
	if m.get("alive", true) and m.get("position") != null:
		t += 1
		if TerrainManager.is_model_hidden(m, fg):
			n += 1
return n == t and t > 0

# F002 (opt-in arm) prices what overwatching now would sell: Hidden in THIS
# turn's coming Shooting phase, x the share of Custodes shooters beyond 15".
var f = FileAccess.open("res://tests/bench_profiles/move_cover_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(2, prof)
AIDecisionMaker._current_player = 2
var snap = GameState.create_snapshot()
return AIDecisionMaker._hidden_forfeit_cost_at(snap.units.U_FLASH_GITZ_A, AIDecisionMaker._get_shootable_enemy_units(snap, 2), snap, int(GameState.get_player_turn_index()))

# configure() clears profiles: the opt-in arm again, for Player 2.
var f = FileAccess.open("res://tests/bench_profiles/move_cover_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(2, prof)
return true

# SHIPPED-DEFAULT CHECK: the profile cleared, the same window has no Hidden line.
AIDecisionMaker.clear_player_profile(2)
var w = PhaseManager.get_current_phase_instance().get_pending_stratagem_window()
var offer = {}
for o in w.get("offers", []):
	if str(o.get("stratagem_id", "")) == "fire_overwatch_11e":
		offer = o
if offer.is_empty():
	return "no offer"
var fo = AIDecisionMaker._decide_fire_overwatch_window_11e(offer, int(GameState.state["players"]["2"]["cp"]))
return str(fo.get("considered", [])).contains("Hidden")
